 $shop=trim((string)input('shop_name'));$owner=trim((string)input('owner_name'));$mobile=trim((string)input('mobile'));$email=filter_var(input('email'),FILTER_VALIDATE_EMAIL)?:null;$lat=(float)input('latitude');$lon=(float)input('longitude');$commission=(float)input('commission_rate',0);$escrow=(float)input('escrow_balance',0);$kyc=strtoupper((string)input('kyc_status','PENDING'));$bank=strtoupper((string)input('bank_verification_status','PENDING'));$status=strtoupper((string)input('status','DRAFT'));
 $valid=['DRAFT','PENDING_KYC','PENDING_BANK','PENDING_APPROVAL','VERIFIED','ACTIVE','REJECTED','SUSPENDED','CLOSED','BLOCKED','INACTIVE'];if($shop===''||$owner===''||$mobile===''||$lat<-90||$lat>90||$lon<-180||$lon>180||$commission<0||$commission>100||$escrow<0||!in_array($kyc,['PENDING','APPROVED','VERIFIED','REJECTED'],true)||!in_array($bank,['PENDING','VERIFIED','REJECTED'],true)||!in_array($status,$valid,true))throw new InvalidArgumentException('Enter valid shop, owner, coordinates, KYC, banking and commercial values.');
 $idProof=trim((string)input('identity_proof_path'));$addressProof=trim((string)input('address_proof_path'));$cheque=trim((string)input('cancelled_cheque_path'));$account=trim((string)input('bank_account_number'));$ifsc=strtoupper(trim((string)input('bank_ifsc')));$otp=input('mobile_otp_verified')==='1';$kycOk=$otp&&$kyc==='VERIFIED'&&$idProof!==''&&$addressProof!=='';$bankOk=$bank==='VERIFIED'&&$cheque!==''&&$account!==''&&$ifsc!==''&&trim((string)input('bank_account_holder'))!=='';
