 $gstDoc=trim((string)input('gst_document_path'))?:null;$sql='INSERT INTO vendors(vendor_code,name,shop_name,business_category,owner_name,email,mobile,mobile_otp_verified,address,owner_address,logo_path,cover_image_path,youtube_promo_url,latitude,longitude,proximity_radius_m,gstin,gst_document_path,identity_proof_path,address_proof_path,cancelled_cheque_path,bank_account_holder,bank_account_number,bank_ifsc,bank_branch,settlement_upi,commission_rate,commission_type,commission_rule,escrow_balance,settlement_cycle,bank_verification_status,kyc_status,onboarding_notes,vendor_qr_payload,status,created_by) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)';
 $pdo->prepare($sql)->execute([$code,$owner,$shop,trim((string)input('category'))?:null,$owner,$email,$mobile,$otp?1:0,trim((string)input('address')),trim((string)input('owner_address'))?:null,$logo,$cover,trim((string)input('youtube_promo_url'))?:null,$lat,$lon,(int)input('proximity_radius_m',300),trim((string)input('gstin'))?:null,$gstDoc,$idProof?:null,$addressProof?:null,$cheque?:null,trim((string)input('bank_account_holder'))?:null,$account?:null,$ifsc?:null,trim((string)input('bank_branch'))?:null,trim((string)input('settlement_upi'))?:null,$commission,strtoupper((string)input('commission_type','PERCENTAGE')),trim((string)input('commission_rule'))?:null,$escrow,strtoupper((string)input('settlement_cycle','DAILY')),$bank,$kyc,trim((string)input('onboarding_notes'))?:null,$qr,$status,admin()['id']]);audit_log((int)admin()['id'],'VENDOR_ONBOARDED','vendors',$code);$pdo->commit();flash('success','Vendor '.$code.' saved as '.$status.($qr?'. Active QR payload generated.':'. QR remains locked until verification is complete.'));
